manifest = "/workspace/dot-files/knowledge/ontario-gyms/luna-conversion-assignments.json" |> File.read!() |> Jason.decode!() |> Map.fetch!("2")
allowed = (Enum.map(manifest["first_ten"], & &1["id"]) ++ manifest["remaining_ids"]) |> MapSet.new()
targets = [96, 271, 272, 273, 274, 275, 276]
unless Enum.all?(targets, &MapSet.member?(allowed, &1)), do: raise "target outside worker-2 manifest"
r = ResearchSource.load(); e = Map.new(r.events, &{&1["id"], &1})
expected = %{96 => 8, 271 => 11, 272 => 11, 273 => 11, 274 => 11, 275 => 11, 276 => 11}
unless Enum.all?(expected, fn {id, gym} -> e[id]["gym_id"] == gym end), do: raise "research gym lookup mismatch"
put! = fn attrs, sessions ->
  unless MapSet.member?(allowed, attrs.id), do: raise "unguarded write #{attrs.id}"
  case Import.put_listing(attrs, sessions) do
    {:ok, l} -> IO.puts("repaired #{l.id}: #{length(l.occurrences)} occurrences, published=#{l.published}")
    {:error, cs} -> IO.inspect(cs.errors, label: "FAILED #{attrs.id}"); raise "repair failed #{attrs.id}"
  end
end
